{"command":"python3 - <<'PY'
import subprocess, os, tempfile, itertools
EXE="/workspace/executable"
def batch(strings, pat=r"^(\S+)$"):
    d=tempfile.mkdtemp()
    for i,s in enumerate(strings):
        open(os.path.join(d,f"f{i:04}.txt"),'w').write(s+"\n")
    r=subprocess.run([EXE,d,"--additional-pattern",pat],capture_output=True,text=True,cwd=d)
    flagged=set()
    for line in r.stdout.splitlines():
        name=os.path.basename(line.split(":")[0])
        try: flagged.add(int(name[1:5]))
        except: pass
    return [i in flagged for i in range(len(strings))]
# binary strings counts
for alphabet in [('a','b'),('a','c'),('x','y'),('a','A'),('e','t'),('m','s'),('d','g')]:
    strings=[]
    labels=[]
    for na in range(0,9):
        for nb in range(0,9):
            if na+nb==0 or na+nb>8: continue
            s=alphabet[0]*na+alphabet[1]*nb
            strings.append(s); labels.append((na,nb))
    res=batch(strings)
    print("alphabet",alphabet)
    # print grid rows na, cols nb
    print("   "+" ".join(str(nb) for nb in range(9)))
    grid={}
    for (na,nb),r in zip(labels,res): grid[(na,nb)]=r
    for na in range(9):
        row=[]
        for nb in range(9):
            if (na,nb) in grid: row.append('T' if grid[(na,nb)] else '.')
            else: row.append(' ')
        print(na, " ".join(row))
    print()
PY"}

