import subprocess, os, tempfile, random, string
EXE="/workspace/executable"
def batch_generic(strings):
    d=tempfile.mkdtemp()
    for i,s in enumerate(strings):
        open(os.path.join(d,f"f{i:04}.txt"),'w').write(f'api_key = "{s}"\n')
    r=subprocess.run([EXE,d],capture_output=True,text=True,cwd=d)
    flagged=set()
    for line in r.stdout.splitlines():
        name=os.path.basename(line.split(":")[0])
        try: flagged.add(int(name[1:5]))
        except: pass
    return [i in flagged for i in range(len(strings))]
random.seed(123)
for charset_name, charset in [("lower",string.ascii_lowercase),("upper",string.ascii_uppercase),("alnum mixed",string.ascii_letters+string.digits)]:
    for n in [16,20,30]:
        samples=[''.join(random.choice(charset) for _ in range(n)) for _ in range(40)]
        res=batch_generic(samples)
        print(charset_name, n, sum(res)/len(res), samples[:3], res[:10])
