import subprocess, os, tempfile, random, string, math, json, collections
EXE="/workspace/executable"
def batch(strings, pat=r"^(\S+)$"):
    d=tempfile.mkdtemp()
    for i,s in enumerate(strings):
        # ensure no newline/space issues: strings are \S
        open(os.path.join(d,f"f{i:05}.txt"),'w',encoding='utf-8').write(s+"\n")
    r=subprocess.run([EXE,d,"--additional-pattern",pat],capture_output=True,text=True,cwd=d)
    flagged=set()
    for line in r.stdout.splitlines():
        name=os.path.basename(line.split(":")[0])
        try: flagged.add(int(name[1:5]))
        except: pass
    return [i in flagged for i in range(len(strings))]

random.seed(42)
strings=[]
# diverse generators
charsets=[string.ascii_lowercase, string.ascii_uppercase, string.digits, string.ascii_letters, string.ascii_letters+string.digits, string.printable.strip()]
words=["password","secret","hello","world","master","dragon","correct","horse","battery","staple","the","quick","brown","fox","admin","login","welcome","letmein","computer","internet"]
for n in [3,4,5,6,7,8,10,12,14,16,18,20,25,30,40,60]:
    for charset in charsets[:5]:
        for _ in range(30):
            strings.append(''.join(random.choice(charset) for _ in range(n)))
    for _ in range(20):
        strings.append(''.join(random.choice(words) for _ in range(5))[:n].ljust(n,'x') if n>=3 else "abc")
    for _ in range(20):
        # pronounceable: consonant vowel alternating
        s=''
        while len(s)<n:
            s+=random.choice("bcdfghjklmnpqrstvwxz")+random.choice("aeiou")
        strings.append(s[:n])
    for _ in range(10):
        strings.append(random.choice(charsets[0])*n)

strings=[s.replace(' ','').replace('\n','') for s in strings if s.strip()]
# dedup preserve
seen=set(); uniq=[]
for s in strings:
    if s not in seen:
        seen.add(s); uniq.append(s)
strings=uniq
labels=batch(strings)
json.dump([{"s":s,"y":int(y)} for s,y in zip(strings,labels)], open("/tmp/data.json","w"))
print(len(strings), sum(labels))
PY
python3 /tmp/gen_data.py"}

