use ignore::gitignore::GitignoreBuilder;
use ignore::WalkBuilder;
use std::path::Path;
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode = &args[1];
    if mode=="matched" {
        let root = &args[2];
        let pat = &args[3];
        let mut b = GitignoreBuilder::new(root);
        b.add_line(None, pat).unwrap();
        let gi = b.build().unwrap();
        for p in &args[4..] {
            let m = gi.matched(Path::new(p), false);
            let md = gi.matched(Path::new(p), true);
            println!("{} -> ignore={} dir_ignore={}", p, m.is_ignore(), md.is_ignore());
        }
