        // args: walk root, custom flag
        let root = &args[2];
        let mut wb = WalkBuilder::new(root);
        wb.add_custom_ignore_filename(args[3].clone());
        wb.hidden(false);
        for e in wb.build() {
            match e { Ok(en)=> println!("{}", en.path().display()), Err(e)=> println!("ERR {}", e)}
        }
    } else if mode=="walk_matchedignore" {
        println!("n/a");
    }
}
