use ignore::gitignore::{GitignoreBuilder, Gitignore};
use std::path::Path;
fn check(gi: &Gitignore, paths:&[String]) {
    for p in paths {
        let m = gi.matched(Path::new(p), false);
        println!("  {} ignore={}", p, m.is_ignore());
    }
}
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode=&args[1];
    let file=&args[2];
    let paths=&args[3..];
    if mode=="add" {
        let mut b = GitignoreBuilder::new("");
        b.add(file);
        let gi=b.build().unwrap();
        check(&gi, paths);
    } else if mode=="global" {
        let mut b = GitignoreBuilder::new("");
        b.add(file);
        let (gi,err)=b.build_global();
        println!("err={:?}", err);
        check(&gi, paths);
    } else if mode=="addroot" {
        let mut b = GitignoreBuilder::new(&args[3]);
        b.add(file);
        let gi=b.build().unwrap();
        check(&gi, &args[4..].to_vec());
    }
}
