fn default_sources(source_files: &[PathBuf]) -> Vec<PathBuf> {
    if source_files.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        source_files.to_vec()
    }
}

fn run(args: Args) -> Result<bool> {
    let sources = default_sources(&args.source_files);
    if args.install_pre_commit {
        if args.strict_ignore {
            bail!("--strict-ignore is not a valid option when installing pre-commits. Use --install-pre-commit alone");
        }
        if args.only_matching {
            bail!("--only-matching is not a valid option when installing pre-commits. Use --install-pre-commit alone");
        }
        for path in &sources {
            install_pre_commit(path)?;
        }
        return Ok(false);
    }

    let secrets_ignore = SecretsIgnore::load()?;

    // Build the combined regex exactly as a parenthesised alternation.
    let mut patterns: Vec<&str> = PREDEFINED_PATTERNS.to_vec();
    patterns.extend(args.additional_patterns.iter().map(|s| s.as_str()));
    let pattern_string = format!("({})", patterns.join("|"));
    let regex = Regex::new(&pattern_string).map_err(anyhow::Error::from)?;

    let found = Arc::new(AtomicBool::new(false));
    let stdout_lock = Arc::new(Mutex::new(()));

    let mut builder = WalkBuilder::new(&sources[0]);
    for path in &sources[1..] {
        builder.add(path);
    }

    let only_matching = args.only_matching;
    let strict_ignore = args.strict_ignore;
    let shared = Arc::new(Shared {
        regex,
        secrets_ignore,
        found: found.clone(),
        stdout_lock,
        only_matching,
        strict_ignore,
    });

    builder.build_parallel().run(|| {
        let shared = shared.clone();
        Box::new(move |entry| {
            match entry {
                Err(err) => {
                    eprintln!("{err}");
                    WalkState::Continue
                }
                Ok(entry) => shared.visit(entry),
            }
        })
    });

    Ok(found.load(Ordering::Relaxed))
}

struct Shared {
    regex: Regex,
    secrets_ignore: SecretsIgnore,
    found: Arc<AtomicBool>,
    stdout_lock: Arc<Mutex<()>>,
    only_matching: bool,
    strict_ignore: bool,
}

impl Shared {
    fn visit(&self, entry: ignore::DirEntry) -> WalkState {
        let path = entry.path();
        let depth = entry.depth();
        let ft = match entry.file_type() {
            Some(ft) => ft,
            None => return WalkState::Continue,
        };

        if ft.is_dir() {
            if depth == 0 && !self.strict_ignore {
                return WalkState::Continue;
            }
            if depth == 0 {
                if self.secrets_ignore.is_strict_ignored(path, true) {
                    return WalkState::Skip;
                } else {
                    return WalkState::Continue;
                }
            }
            if self.secrets_ignore.is_traversal_ignored(path, true) {
                return WalkState::Skip;
            }
            return WalkState::Continue;
        }

        if !ft.is_file() {
            return WalkState::Continue;
        }

        // regular file
        if depth == 0 {
            if self.strict_ignore && self.secrets_ignore.is_strict_ignored(path, false) {
                return WalkState::Continue;
            }
            // non-strict: explicit files are always scanned
        } else if self.secrets_ignore.is_traversal_ignored(path, false) {
            return WalkState::Continue;
        }

        self.scan_file(path);
        WalkState::Continue
    }

    fn scan_file(&self, path: &Path) {
        let bytes = match std::fs::read(path) {
            Ok(b) => b,
            Err(err) => {
                eprintln!("{}: {err}", path.display());
                return;
            }
        };
        let decoded = decode_file_bytes(bytes);
        // scan line by line (split on \n, keep \r)
        let mut start: usize = 0;
        let mut line_num: usize = 1;
        let data = &decoded;
        while start < data.len() {
            let end = match data[start..].iter().position(|&b| b == b'\n') {
                Some(pos) => start + pos,
                None => data.len(),
            };
            let line = &data[start..end];
            self.scan_line(path, line_num, line);
            if end == data.len() {
                break;
            }
            start = end + 1;
            line_num += 1;
        }
    }

    fn scan_line(&self, path: &Path, line_num: usize, line: &[u8]) {
        let secrets = find_secrets(
            &self.regex,
            line,
            &self.secrets_ignore.secrets,
        );
        if secrets.is_empty() {
            return;
        }
        self.found.store(true, Ordering::Relaxed);
        let _guard = self.stdout_lock.lock().unwrap();
        let stdout = std::io::stdout();
        let mut handle = stdout.lock();
        if self.only_matching {
            for secret in &secrets {
                let _ = write!(handle, "{}:{}:", path.display(), line_num);
                let _ = handle.write_all(secret);
                let _ = writeln!(handle);
            }
        } else {
            let _ = write!(handle, "{}:{}:", path.display(), line_num);
            let _ = handle.write_all(line);
            let _ = writeln!(handle);
        }
    }
}

/// Find qualifying secrets in a single line (without trailing \n).
/// Returns the byte ranges' contents for each qualifying secret, in order.
fn find_secrets(regex: &Regex, line: &[u8], ignored_secrets: &HashSet<String>) -> Vec<Vec<u8>> {
    let mut results: Vec<Vec<u8>> = Vec::new();
    if line.is_empty() {
        return results;
    }
    let mut offset: usize = 0;
    let mut prev_secret_end: Option<usize> = None;
    let mut prev_secret_nonempty = false;
    while offset < line.len() {
        let caps = match regex.captures_at(line, offset) {
            Ok(Some(c)) => c,
            Ok(None) => break,
            Err(_) => break,
        };
        // Determine the selected capture: first participating group after
        // group 0 (whole match) and group 1 (the outer alternation group).
        let mut selected: Option<regex::bytes::Match> = None;
        let mut has_selected_group = false;
        for (i, group) in caps.iter().enumerate() {
            if i < 2 {
                continue;
            }
            if let Some(m) = group {
                selected = Some(m);
                has_selected_group = true;
                break;
            }
        }
        let (secret_start, secret_end, secret_bytes): (usize, usize, Vec<u8>);
        if has_selected_group {
            let m = selected.unwrap();
            secret_start = m.start();
            secret_end = m.end();
            secret_bytes = m.as_bytes().to_vec();
            // randomness test on the selected group
            let text = String::from_utf8_lossy(&secret_bytes);
            let is_ign = ignored_secrets.contains(text.as_ref());
            if !is_ign && p_random::is_random(&text) {
                // suppress empty secrets that immediately follow a non-empty secret
                let is_empty = secret_start == secret_end;
                if !(is_empty && prev_secret_nonempty && prev_secret_end == Some(secret_start)) {
                    results.push(secret_bytes);
                }
            }
        } else {
            let m = caps.get(0).unwrap();
            secret_start = m.start();
            secret_end = m.end();
            secret_bytes = m.as_bytes().to_vec();
            let text = String::from_utf8_lossy(&secret_bytes);
            let is_ign = ignored_secrets.contains(text.as_ref());
            if !is_ign {
                let is_empty = secret_start == secret_end;
                if !(is_empty && prev_secret_nonempty && prev_secret_end == Some(secret_start)) {
                    results.push(secret_bytes);
                }
            }
        }
        // Advance by the secret's end.
        let is_empty_secret = secret_start == secret_end;
        if secret_end <= offset && secret_end == secret_start {
            // empty match at the search offset: advance one char
            offset = next_char_boundary(line, secret_end);
            prev_secret_end = Some(secret_end);
            prev_secret_nonempty = false;
        } else if is_empty_secret {
            // empty secret elsewhere
            let suppressed = prev_secret_nonempty && prev_secret_end == Some(secret_start);
            offset = next_char_boundary(line, secret_end);
            prev_secret_end = Some(secret_end);
            prev_secret_nonempty = false;
            let _ = suppressed;
        } else {
            offset = secret_end;
            prev_secret_end = Some(secret_end);
            prev_secret_nonempty = true;
        }
    }
    results
}

fn next_char_boundary(line: &[u8], pos: usize) -> usize {
    if pos >= line.len() {
        return pos + 1;
    }
    // line is bytes; for UTF-8 safety advance over one UTF-8 char if valid.
    let mut n = pos + 1;
    while n < line.len() && (line[n] & 0b1100_0000) == 0b1000_0000 {
        n += 1;
    }
    n
}

fn decode_file_bytes(bytes: Vec<u8>) -> Vec<u8> {
    if bytes.starts_with(&[0xFF, 0xFE]) {
        // UTF-16LE
        let units: Vec<u16> = bytes[2..]
            .chunks_exact(2)
            .map(|c| u16::from_le_bytes([c[0], c[1]]))
            .collect();
        let s: String = char::decode_utf16(units).map(|r| r.unwrap_or('\u{FFFD}')).collect();
        return s.into_bytes();
    }
    if bytes.starts_with(&[0xFE, 0xFF]) {
        let units: Vec<u16> = bytes[2..]
            .chunks_exact(2)
            .map(|c| u16::from_be_bytes([c[0], c[1]]))
            .collect();
        let s: String = char::decode_utf16(units).map(|r| r.unwrap_or('\u{FFFD}')).collect();
        return s.into_bytes();
    }
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return bytes[3..].to_vec();
    }
    bytes
}

fn install_pre_commit(dir: &Path) -> Result<()> {
    let git_dir = dir.join(".git");
    if !git_dir.exists() {
        return Err(anyhow!(".git directory not found"));
    }
    let hook_path = git_dir.join("hooks").join("pre-commit");
    let hook_with_nl = format!("{HOOK_LINE}\n");
    if hook_path.exists() {
        let contents = std::fs::read_to_string(&hook_path)?;
        if contents.contains(&hook_with_nl) {
            return Err(anyhow!("pre-commit hook has already been installed"));
        }
        let mut file = open_hook_file(&hook_path, true)?;
        file.write_all(hook_with_nl.as_bytes())?;
        return Ok(());
    }
    let mut file = open_hook_file(&hook_path, false)?;
    file.write_all(hook_with_nl.as_bytes())?;
    Ok(())
}

fn open_hook_file(path: &Path, append: bool) -> Result<std::fs::File> {
    let mut opts = std::fs::OpenOptions::new();
    opts.create(true).write(true);
    if append {
        opts.append(true);
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.mode(0o744);
    }
    Ok(opts.open(path)?)
}
