                    results.push(secret_bytes);
                }
            }
        } else {
            let m = caps.get(0).unwrap();
            secret_start = m.start();
            secret_end = m.end();
            secret_bytes = m.as_bytes().to_vec();
            let text = String::from_utf8_lossy(&secret_bytes);
