        let mut file = open_hook_file(&hook_path, true)?;
        file.write_all(hook_with_nl.as_bytes())?;
        return Ok(());
    }
    let mut file = open_hook_file(&hook_path, false)?;
    file.write_all(hook_with_nl.as_bytes())?;
    Ok(())
}

fn open_hook_file(path: &Path, append: bool) -> Result<std::fs::File> {
    let mut opts = std::fs::OpenOptions::new();
    opts.create(true).write(true);
    if append {
        opts.append(true);
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.mode(0o744);
    }
    Ok(opts.open(path)?)
}
