        let s: String = char::decode_utf16(units).map(|r| r.unwrap_or('\u{FFFD}')).collect();
        return s.into_bytes();
    }
    if bytes.starts_with(&[0xFE, 0xFF]) {
        let units: Vec<u16> = bytes[2..]
            .chunks_exact(2)
            .map(|c| u16::from_be_bytes([c[0], c[1]]))
            .collect();
        let s: String = char::decode_utf16(units).map(|r| r.unwrap_or('\u{FFFD}')).collect();
        return s.into_bytes();
    }
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return bytes[3..].to_vec();
    }
    bytes
}

fn install_pre_commit(dir: &Path) -> Result<()> {
    let git_dir = dir.join(".git");
    if !git_dir.exists() {
        return Err(anyhow!(".git directory not found"));
    }
    let hook_path = git_dir.join("hooks").join("pre-commit");
    let hook_with_nl = format!("{HOOK_LINE}\n");
    if hook_path.exists() {
        let contents = std::fs::read_to_string(&hook_path)?;
        if contents.contains(&hook_with_nl) {
            return Err(anyhow!("pre-commit hook has already been installed"));
        }
        let mut file = open_hook_file(&hook_path, true)?;
        file.write_all(hook_with_nl.as_bytes())?;
        return Ok(());
    }
    let mut file = open_hook_file(&hook_path, false)?;
    file.write_all(hook_with_nl.as_bytes())?;
    Ok(())
}

fn open_hook_file(path: &Path, append: bool) -> Result<std::fs::File> {
    let mut opts = std::fs::OpenOptions::new();
    opts.create(true).write(true);
    if append {
        opts.append(true);
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.mode(0o744);
    }
    Ok(opts.open(path)?)
}
