use anyhow::Result;
use ignore::gitignore::{Gitignore, GitignoreBuilder};
use std::collections::HashSet;
use std::path::{Path, PathBuf};

#[derive(Debug)]
pub struct SecretsIgnore {
    pub secrets: HashSet<String>,
    strict: Option<Gitignore>,
    patterns: Vec<Pattern>,
    pub glob_errors: Vec<String>, // fully formatted error messages (without trailing \n)
    pub has_secrets_section: bool,
}

#[derive(Debug, Clone)]
struct Pattern {
    whitelist: bool,
    only_dir: bool,
    // expanded pattern variants as component globs; a synthetic leading "**"
    // component is applied at match time.
    variants: Vec<Vec<CompPat>>,
}

#[derive(Debug, Clone)]
enum CompPat {
    StarStar,
    Component(Vec<Token>),
}

#[derive(Debug, Clone)]
enum Token {
    Char(char),
    Star,
    Question,
    Class { negated: bool, items: Vec<(char, char)> },
}

impl SecretsIgnore {
    pub fn empty() -> Self {
        SecretsIgnore {
            secrets: HashSet::new(),
            strict: None,
            patterns: Vec::new(),
            glob_errors: Vec::new(),
            has_secrets_section: false,
        }
    }

    pub fn load() -> Result<Self> {
        let path = Path::new(".secretsignore");
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                return Ok(Self::empty());
            }
            Err(e) => return Err(anyhow::Error::from(e)),
        };
        Ok(Self::parse(&content))
    }

    pub fn parse(content: &str) -> Self {
        let mut secrets: HashSet<String> = HashSet::new();
        let mut raw_patterns: Vec<String> = Vec::new();
        let mut in_secrets = false;
        let mut has_secrets_section = false;
        for line in content.split('\n') {
            if line.ends_with("[secrets]") {
                in_secrets = true;
                has_secrets_section = true;
                continue;
            }
            if in_secrets {
                secrets.insert(line.to_string());
            } else {
                raw_patterns.push(line.to_string());
            }
        }

        // Build strict matcher using the ignore crate (errors silently ignored)
        let abs_path: PathBuf = std::env::current_dir()
            .map(|d| d.join(".secretsignore"))
            .unwrap_or_else(|_| PathBuf::from(".secretsignore"));
        let mut builder = GitignoreBuilder::new(".");
        for line in &raw_patterns {
            let _ = builder.add_line(Some(abs_path.clone()), line);
        }
        let strict = builder.build().ok();

        // Build our traversal patterns
        let mut patterns = Vec::new();
        let mut glob_errors = Vec::new();
        // Error location: if there's a secrets section the original tool
        // builds its matcher from a temporary file, so error messages point
        // at a temp file in the system temp directory. Reproduce the shape
        // of that path.
        let err_path = if has_secrets_section {
            temp_error_path()
        } else {
            abs_path.display().to_string()
        };
        for (idx, raw) in raw_patterns.iter().enumerate() {
            match Pattern::parse(raw) {
                Ok(Some(p)) => patterns.push(p),
                Ok(None) => {}
                Err(msg) => {
                    glob_errors.push(format!(
                        "{err_path}: line {}: error parsing glob '{}': {}",
                        idx + 1,
                        raw,
                        msg
                    ));
                }
            }
        }

        SecretsIgnore {
            secrets,
            strict,
            patterns,
            glob_errors,
            has_secrets_section,
        }
    }

    pub fn is_strict_ignored(&self, path: &Path, is_dir: bool) -> bool {
        let gi = match &self.strict {
            Some(g) => g,
            None => return false,
        };
        for ancestor in path.ancestors() {
            if ancestor.as_os_str().is_empty() {
                continue;
            }
            let anc_is_dir = if ancestor == path { is_dir } else { true };
            // candidate path variants
            let mut candidates: Vec<PathBuf> = vec![ancestor.to_path_buf()];
            if ancestor.is_relative() {
                candidates.push(PathBuf::from(".").join(ancestor));
            } else if ancestor.is_absolute() {
                if let Ok(cwd) = std::env::current_dir() {
                    if let Ok(rel) = ancestor.strip_prefix(&cwd) {
                        if !rel.as_os_str().is_empty() {
                            candidates.push(PathBuf::from(".").join(rel));
                            candidates.push(rel.to_path_buf());
                        }
                    }
                }
            }
            for cand in candidates {
                if gi.matched(&cand, anc_is_dir).is_ignore() {
                    return true;
                }
            }
        }
        false
    }

    pub fn is_traversal_ignored(&self, path: &Path, is_dir: bool) -> bool {
        let comps = path_components(path);
        let mut ignored = false;
        for pat in &self.patterns {
            if pat.only_dir && !is_dir {
                continue;
            }
            if pat.matches(&comps) {
                ignored = !pat.whitelist;
            }
        }
        ignored
    }
}

fn temp_error_path() -> String {
    // Mimic a temporary file name like /tmp/.tmpAbC123
    let mut seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64 ^ (std::process::id() as u64) << 17)
        .unwrap_or(0x9e3779b97f4a7c15);
    let chars: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    let mut name = String::from(".tmp");
    for _ in 0..6 {
        // xorshift
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        name.push(chars[(seed % 62) as usize] as char);
    }
    std::env::temp_dir().join(name).display().to_string()
}

fn path_components(path: &Path) -> Vec<String> {
    let mut comps = Vec::new();
    for comp in path.components() {
        use std::path::Component::*;
        match comp {
            CurDir => {}
            RootDir => comps.push("/".to_string()),
            ParentDir => comps.push("..".to_string()),
            Normal(s) => comps.push(s.to_string_lossy().into_owned()),
            Prefix(p) => comps.push(p.as_os_str().to_string_lossy().into_owned()),
        }
    }
    comps
}

impl Pattern {
    fn parse(raw: &str) -> std::result::Result<Option<Self>, String> {
        let mut line = raw;
        // comments
        if line.starts_with('#') {
            return Ok(None);
        }
        if let Some(stripped) = line.strip_prefix("\\#") {
            // literal leading #
            let mut owned = String::from("#");
            owned.push_str(stripped);
            // reassign via leak-free approach: build a new string in a variable
            // Simplify by reconstructing line as owned
            return Self::parse_inner_owned(owned, raw);
        }
        let _ = &mut line;
        Self::parse_inner(raw)
    }

    fn parse_inner(raw: &str) -> std::result::Result<Option<Self>, String> {
        Self::parse_inner_owned(raw.to_string(), raw)
    }

    fn parse_inner_owned(mut line: String, raw: &str) -> std::result::Result<Option<Self>, String> {
        let _ = raw;
        if line.starts_with('#') {
            return Ok(None);
        }
        if line.is_empty() {
            return Ok(None);
        }
        let mut whitelist = false;
        if let Some(rest) = line.strip_prefix('!') {
            whitelist = true;
            line = rest.to_string();
        } else if let Some(rest) = line.strip_prefix("\\!") {
            line = format!("!{rest}");
        }
        // trailing unescaped spaces are stripped (gitignore rule)
        loop {
            if line.ends_with(' ') {
                let bytes = line.as_bytes();
                let mut backslashes = 0;
                let mut i = bytes.len().saturating_sub(1);
                while i > 0 && bytes[i - 1] == b'\\' {
                    backslashes += 1;
                    i -= 1;
                }
                if backslashes % 2 == 0 {
                    line.pop();
                    continue;
                }
            }
            break;
        }
        if line.is_empty() {
            return Ok(None);
        }
        let mut only_dir = false;
        if line.ends_with('/') {
            only_dir = true;
            line.pop();
            if line.is_empty() {
                return Ok(None);
            }
        }
        // Leading slash is an anchoring marker; removing exactly one makes
        // the remaining pattern usable. A doubled leading slash retains an
        // empty first component which will not match.
        let mut pat_str = line.clone();
        if pat_str.starts_with('/') {
            pat_str.remove(0);
        }
        // validate for dangling backslash at end
        {
            let mut chars = pat_str.chars().peekable();
            let mut last_was_escape = false;
            let mut in_class = false;
            while let Some(c) = chars.next() {
                if last_was_escape {
                    last_was_escape = false;
                    continue;
                }
                match c {
                    '\\' => last_was_escape = true,
                    '[' => in_class = true,
                    ']' => in_class = false,
                    _ => {}
                }
            }
            if last_was_escape {
                return Err("dangling '\\'".to_string());
            }
            if in_class {
                return Err("unclosed character class; missing ']'".to_string());
            }
        }
        // Expand braces at the string level
        let expanded = expand_braces(&pat_str)?;
        let mut variants = Vec::new();
        for exp in expanded {
            let comps: Vec<&str> = exp.split('/').collect();
            let mut variant = Vec::new();
            for comp in comps {
                if comp == "**" {
                    variant.push(CompPat::StarStar);
                } else {
                    variant.push(CompPat::Component(parse_component(comp)?));
                }
            }
            variants.push(variant);
        }
        Ok(Some(Pattern {
            whitelist,
            only_dir,
            variants,
        }))
    }

    fn matches(&self, cand: &[String]) -> bool {
        // Prefixed ** semantics: try full match with a synthetic leading **
        for variant in &self.variants {
            let mut full: Vec<CompPat> = Vec::with_capacity(variant.len() + 1);
            full.push(CompPat::StarStar);
            full.extend(variant.iter().cloned());
            if glob_match(&full, cand) {
                return true;
            }
        }
        false
    }
}

fn parse_component(comp: &str) -> std::result::Result<Vec<Token>, String> {
    let mut tokens = Vec::new();
    let mut chars = comp.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\\' => match chars.next() {
                Some(escaped) => tokens.push(Token::Char(escaped)),
                None => return Err("dangling '\\'".to_string()),
            },
            '*' => tokens.push(Token::Star),
            '?' => tokens.push(Token::Question),
            '[' => {
                let mut negated = false;
                let mut items: Vec<(char, char)> = Vec::new();
                let mut first = true;
                let mut closed = false;
                // optional negation
                if let Some(&nc) = chars.peek() {
                    if nc == '!' || nc == '^' {
                        // `^` is only negation in some glob engines after `[`;
                        // the ignore crate treats `[!...]` as negated and `^` literally
                        // only when it is the first char in globset it is literal.
                        // We treat '^' as literal to match globset more closely,
                        // except '!' which is negation.
                        if nc == '!' {
                            negated = true;
                            chars.next();
                        }
                    }
                }
                let mut prev: Option<char> = None;
                while let Some(cc) = chars.next() {
                    if cc == ']' && !first {
                        closed = true;
                        break;
                    }
                    first = false;
                    let cur = if cc == '\\' {
                        match chars.next() {
                            Some(e) => e,
                            None => return Err("dangling '\\'".to_string()),
                        }
                    } else {
                        cc
                    };
                    if cur == '-' {
                        // range with previous
                        if let Some(lo) = prev.take() {
                            // next char is the high end
                            if let Some(&peekc) = chars.peek() {
                                if peekc == ']' {
                                    // trailing - is literal
                                    items.push((lo, lo));
                                    items.push(('-', '-'));
                                    continue;
                                }
                            }
                            let hi_raw = chars.next().unwrap();
                            let hi = if hi_raw == '\\' {
                                chars.next().ok_or("dangling '\\'")?
                            } else {
                                hi_raw
                            };
                            items.push((lo, hi));
                            continue;
                        } else {
                            items.push(('-', '-'));
                            continue;
                        }
                    }
                    if let Some(p) = prev.take() {
                        items.push((p, p));
                    }
                    prev = Some(cur);
                }
                if !closed {
                    return Err("unclosed character class; missing ']'".to_string());
                }
                if let Some(p) = prev.take() {
                    items.push((p, p));
                }
                tokens.push(Token::Class { negated, items });
            }
            other => tokens.push(Token::Char(other)),
        }
    }
    Ok(tokens)
}

fn expand_braces(pat: &str) -> std::result::Result<Vec<String>, String> {
    // Find first unescaped '{'
    let chars: Vec<char> = pat.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' {
            i += 2;
            continue;
        }
        if chars[i] == '{' {
            // find matching close with nesting
            let mut depth = 0i32;
            let mut j = i;
            let mut close: Option<usize> = None;
            while j < chars.len() {
                if chars[j] == '\\' {
                    j += 2;
                    continue;
                }
                if chars[j] == '{' {
                    depth += 1;
                } else if chars[j] == '}' {
                    depth -= 1;
                    if depth == 0 {
                        close = Some(j);
                        break;
                    }
                }
                j += 1;
            }
            let close = match close {
                Some(c) => c,
                None => return Err("unclosed alternates; missing '}'".to_string()),
            };
            let inside: String = chars[i + 1..close].iter().collect();
            // split top-level commas
            let mut parts: Vec<String> = Vec::new();
            let mut depth2 = 0i32;
            let mut cur = String::new();
            let inside_chars: Vec<char> = inside.chars().collect();
            let mut k = 0;
            while k < inside_chars.len() {
                let c = inside_chars[k];
                if c == '\\' && k + 1 < inside_chars.len() {
                    cur.push(c);
                    cur.push(inside_chars[k + 1]);
                    k += 2;
                    continue;
                }
                if c == '{' {
                    depth2 += 1;
                } else if c == '}' {
                    depth2 -= 1;
                }
                if c == ',' && depth2 == 0 {
                    parts.push(cur.clone());
                    cur.clear();
                } else {
                    cur.push(c);
                }
                k += 1;
            }
            parts.push(cur);
            let prefix: String = chars[..i].iter().collect();
            let suffix: String = chars[close + 1..].iter().collect();
            let mut results = Vec::new();
            for part in parts {
                let combined = format!("{prefix}{part}{suffix}");
                results.extend(expand_braces(&combined)?);
            }
            return Ok(results);
        }
        i += 1;
    }
    Ok(vec![pat.to_string()])
}

fn glob_match(pattern: &[CompPat], cand: &[String]) -> bool {
    // Recursive match with ** handling
    fn rec(pat: &[CompPat], cand: &[String]) -> bool {
        if pat.is_empty() {
            return cand.is_empty();
        }
        match &pat[0] {
            CompPat::StarStar => {
                // match zero components
                if rec(&pat[1..], cand) {
                    return true;
                }
                if !cand.is_empty() {
                    return rec(pat, &cand[1..]);
                }
                false
            }
            CompPat::Component(tokens) => {
                if cand.is_empty() {
                    return false;
                }
                if component_match(tokens, &cand[0]) {
                    rec(&pat[1..], &cand[1..])
                } else {
                    false
                }
            }
        }
    }
    rec(pattern, cand)
}

fn component_match(tokens: &[Token], text: &str) -> bool {
    let chars: Vec<char> = text.chars().collect();
    fn rec(tokens: &[Token], chars: &[char]) -> bool {
        if tokens.is_empty() {
            return chars.is_empty();
        }
        match &tokens[0] {
            Token::Star => {
                // match zero or more
                if rec(&tokens[1..], chars) {
                    return true;
                }
                if !chars.is_empty() {
                    return rec(tokens, &chars[1..]);
                }
                false
            }
            Token::Question => {
                if chars.is_empty() {
                    false
                } else {
                    rec(&tokens[1..], &chars[1..])
                }
            }
            Token::Char(c) => {
                if !chars.is_empty() && chars[0] == *c {
                    rec(&tokens[1..], &chars[1..])
                } else {
                    false
                }
            }
            Token::Class { negated, items } => {
                if chars.is_empty() {
                    return false;
                }
                let c = chars[0];
                let inside = items.iter().any(|(lo, hi)| c >= *lo && c <= *hi);
                if inside != *negated {
                    rec(&tokens[1..], &chars[1..])
                } else {
                    false
                }
            }
        }
    }
    rec(tokens, &chars)
}
