use std::collections::HashMap;

/// Initial approximation of the randomness test.
/// Returns true if the string looks like a randomly generated secret.
pub fn is_random(text: &str) -> bool {
    if text.is_empty() {
        return false;
    }
    if text.len() >= 171 {
        return true;
    }
    // Shannon entropy over bytes
    let bytes = text.as_bytes();
    let mut counts: HashMap<u8, usize> = HashMap::new();
    for &b in bytes {
        *counts.entry(b).or_insert(0) += 1;
    }
    let len = bytes.len() as f64;
    let mut entropy = 0.0f64;
    for &c in counts.values() {
        let p = c as f64 / len;
        entropy -= p * p.log2();
    }
    let distinct = counts.len() as f64;
    // Very repetitive strings are not random.
    if distinct <= 1.0 {
        return false;
    }
    entropy > 3.6 && distinct / len > 0.35
}
