    let lower = chars.iter().filter(|c| c.is_lowercase()).count() as f64;
    let upper = chars.iter().filter(|c| c.is_uppercase()).count() as f64;
    let digit = chars.iter().filter(|c| c.is_ascii_digit()).count() as f64;
    let alpha = lower + upper;
    let sym = n - alpha - digit;
    fn class_of(ch: char) -> u8 {{
        if ch.is_lowercase() {{ 0 }} else if ch.is_uppercase() {{ 1 }} else if ch.is_ascii_digit() {{ 2 }} else {{ 3 }}
    }}
    let mut trans = 0usize;
    for w in chars.windows(2) {{
        if class_of(w[0]) != class_of(w[1]) {{ trans += 1; }}
    }}
    let bigrams: std::collections::HashSet<(char, char)> = chars.windows(2).map(|w| (w[0], w[1])).collect();
    let vowels = chars.iter().filter(|c| matches!(c, 'a' | 'e' | 'i' | 'o' | 'u' | 'A' | 'E' | 'I' | 'O' | 'U')).count() as f64;
    let maxfreq = counts.values().copied().max().unwrap_or(0) as f64;
