    let mut cur = 1usize;
    let mut maxsame = 1usize;
    let mut curs = 1usize;
    for w in chars.windows(2) {{
        if (w[1] as i64 - w[0] as i64).abs() == 1 {{ cur += 1; }} else {{ cur = 1; }}
        maxrun = maxrun.max(cur);
        if w[0] == w[1] {{ curs += 1; }} else {{ curs = 1; }}
        maxsame = maxsame.max(curs);
    }}
    if chars.is_empty() {{ maxrun = 0; maxsame = 0; }}
    let ishex = if !chars.is_empty() && chars.iter().all(|c| c.is_ascii_hexdigit()) {{ 1.0 }} else {{ 0.0 }};
    Features {{
        n,
        H: entropy,
        distinct,
        dratio: if n > 0.0 {{ distinct / n }} else {{ 0.0 }},
        lower_f: if n > 0.0 {{ lower / n }} else {{ 0.0 }},
        upper_f: if n > 0.0 {{ upper / n }} else {{ 0.0 }},
        digit_f: if n > 0.0 {{ digit / n }} else {{ 0.0 }},
        sym_f: if n > 0.0 {{ sym / n }} else {{ 0.0 }},
        classes: (lower > 0.0) as u8 as f64 + (upper > 0.0) as u8 as f64 + (digit > 0.0) as u8 as f64 + (sym > 0.0) as u8 as f64,
        trans_r: if n > 1.0 {{ trans as f64 / (n - 1.0) }} else {{ 0.0 }},
        bigram_r: if n > 1.0 {{ bigrams.len() as f64 / (n - 1.0) }} else {{ 0.0 }},
        vowel_f: if alpha > 0.0 {{ vowels / alpha }} else {{ 0.0 }},
        maxfreq_r: if n > 0.0 {{ maxfreq / n }} else {{ 0.0 }},
        seqrun_r: if n > 0.0 {{ maxrun as f64 / n }} else {{ 0.0 }},
        maxsame: maxsame as f64,
        ishex,
        H_over_log_n: if n > 1.0 {{ entropy / n.log2() }} else {{ 0.0 }},
    }}
}}

fn decision_tree(f: &Features) -> bool {{
{tree_code}
}}

