pub fn is_random(text: &str) -> bool {{
    if text.is_empty() {{
        return false;
    }}
    if text.chars().count() <= 2 {{
        return true;
    }}
    if text.len() >= 171 {{
        return true;
    }}
    let f = compute_features(text);
    decision_tree(&f)
}}
