import json, math, collections, glob
texts=[]
for path in glob.glob("/usr/lib/python3.10/*.py")[:200]:
    try: texts.append(open(path,errors="ignore").read())
    except: pass
corpus="\n".join(texts).lower()
counts=collections.defaultdict(collections.Counter); tot=collections.Counter()
