    subset=[d for d in data if bigram_avg(d['s']) is not None and bigram_avg(d['s'])>thresh]
    if subset:
        print(f"thresh {thresh}: subset {len(subset)}, orig true rate {sum(d['y'] for d in subset)/len(subset):.3f}")
