{"command":"python3 - <<'PY'
import pty, os, sys
def run_pty(exe,args):
    pid, fd = pty.fork()
    if pid==0:
        os.execv(exe,[exe]+args)
    out=b""
    try:
        while True:
            data=os.read(fd,1024)
            if not data: break
            out+=data
    except OSError: pass
    os.waitpid(pid,0)
    return out
for exe in ["/workspace/executable","/tmp/myexe"]:
    print(exe, "help via pty:", run_pty(exe,["--help"])[:200])
    print(exe, "err via pty:", run_pty(exe,["--unknown"])[:300])
